---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Change review: Accept or reject each change the agent made, file by file.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change change-review.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './change-review.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'wide', className]} data-c="change-review" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="crx panel">
  <div class="crx-side">
    <div class="crx-sh"><b>3 files changed</b><span class="muted crx-tot num"></span></div>
    <div class="crx-files"></div>
  </div>
  <div class="crx-main">
    <div class="crx-mh"><span class="crx-fn num"></span><span class="crx-sp"></span><button class="pill ghost sm crx-rej">Undo all</button><button class="pill primary sm crx-ok">Keep all</button></div>
    <div class="crx-diff"></div>
  </div>
</div>
  </Fragment></div>
</div>
<script>
  import './change-review.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Change review ---------- */
.crx{display:grid;grid-template-columns:210px 1fr;overflow:hidden;min-height:330px}
@media (max-width:720px){.crx{grid-template-columns:1fr}.crx-side{border-right:0!important;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}}
.crx-side{border-right:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);padding:10px;display:flex;flex-direction:column;gap:6px;min-width:0}
.crx-sh{display:flex;justify-content:space-between;align-items:baseline;padding:var(--dm-s-1) 6px;font-size:12.5px}
.crx-sh b{font-weight:500}
.crx-files{display:flex;flex-direction:column;gap:2px}
.crx-f{display:flex;align-items:center;gap:var(--dm-s-2);padding:7px var(--dm-s-2);border-radius:calc(10px * var(--dm-rk));font-size:12.5px;text-align:left;transition:background .25s;min-width:0}
@media (hover:hover) and (pointer:fine){.crx-f:hover{background:var(--dm-row)}}
.crx-f.on{background:var(--dm-sel)}
.crx-f .nm{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-family:var(--dm-mono);font-size:11.5px}
.crx-f .st{width:16px;height:16px;display:grid;place-items:center;color:var(--dm-faint)}
.crx-f.kept .st{color:var(--dm-ok)}.crx-f.undone .st{color:var(--dm-muted)}
.crx-main{display:flex;flex-direction:column;min-width:0}
.crx-mh{display:flex;align-items:center;gap:6px;padding:10px var(--dm-s-3);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.crx-fn{font-size:12px;font-family:var(--dm-mono);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}
.crx-sp{flex:1}
.crx-diff{padding:var(--dm-s-2) 0;font-family:var(--dm-mono);font-size:12px;line-height:1.75;overflow-x:auto}
.crx-hk{margin:0 10px 10px;border-radius:calc(10px * var(--dm-rk));overflow:auto hidden;transition:opacity .35s}
.crx-hh{display:flex;align-items:center;gap:6px;padding:var(--dm-s-1) 6px var(--dm-s-1) 10px;font-family:var(--dm-sans);font-size:12px;color:var(--dm-fg2);background:var(--dm-chip)}
.crx-hh .sp{flex:1}
.crx-hh .pill{height:24px;padding:0 9px;font-size:12px}
/* each suggestion's Keep is its action: the accent on a tint of it, so it reads as ready to press on the grey bar (a grey
   button there read as disabled), with Undo beside it kept quiet. Once kept, Keep turns to the green done chip, and an
   undone hunk's Undo sits on the surface; pressing either again takes the choice back */
.crx-hh .hk-k{background:color-mix(in srgb,var(--dm-accent) 12%,var(--dm-surface));color:var(--dm-accent-fg)}
@media (hover:hover) and (pointer:fine){.crx-hh .hk-k:hover{background:color-mix(in srgb,var(--dm-accent) 20%,var(--dm-surface))}}
.crx-hk.kept .hk-k{background:var(--dm-ok-bg);color:var(--dm-ok)}
.crx-hk.undone .hk-u{background:var(--dm-surface);color:var(--dm-fg)}
:root:not([data-style="soft"]) .crx-hh .hk-k:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 45%,transparent)}
:root:not([data-style="soft"]) .crx-hk.kept .hk-k:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-ok-mark) 45%,transparent)}
.crx-l{display:flex;position:relative;white-space:pre;padding-right:10px}
.crx-l .ln{width:36px;text-align:right;padding-right:10px;color:var(--dm-muted);flex:none;user-select:none}
.crx-l.add{background:var(--dm-ok-bg)}.crx-l.add .c::before{content:"+ ";color:var(--dm-ok)}
.crx-l.del{background:var(--dm-bad-bg)}.crx-l.del .c::before{content:"− ";color:var(--dm-bad)}
.crx-l:is(.add,.del) .ln{color:var(--dm-fg2)}
.crx-l.ctx .c::before{content:"  "}
.crx-l .cm{position:absolute;left:4px;top:3px;width:18px;height:18px;border-radius:calc(6px * var(--dm-rk));background:var(--dm-accent);color:var(--dm-on-accent);display:grid;place-items:center;opacity:0;transform:scale(.7);transition:opacity .2s,transform .25s var(--dm-ease)}
/* the hunk scrolls sideways and cuts anything outside its last line: the ring is drawn inside, with a gap of the surface
   between it and the fill */
.crx-l .cm:focus-visible{outline-offset:-2px;box-shadow:inset 0 0 0 3.5px var(--dm-surface);opacity:1;transform:none}
@media (hover:hover) and (pointer:fine){.crx-l:hover .cm{opacity:1;transform:none}}
.crx-hk.kept .crx-l.del{display:none}.crx-hk.kept .crx-l.add{background:transparent}.crx-hk.kept .crx-l.add .c::before{content:"  "}
.crx-hk.undone .crx-l.add{display:none}.crx-hk.undone .crx-l.del{background:transparent}.crx-hk.undone .crx-l.del .c::before{content:"  "}
.crx-hk.kept .crx-hh,.crx-hk.undone .crx-hh{color:var(--dm-muted)}
.crx-cmt{font-family:var(--dm-sans);margin:var(--dm-s-1) 10px 6px 36px;display:flex;gap:6px;align-items:center;padding:6px;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent)}
@supports (corner-shape:squircle){.crx-cmt:not(.sent){corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.crx-cmt input{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:12.5px;color:var(--dm-fg);padding:0 6px}
.crx-cmt:has(input:focus){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.crx-cmt.sent{background:var(--dm-sel);box-shadow:none;font-size:12.5px;padding:6px 10px}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, enter, html, stagger, swap } from '../core/core.js';
DM.def('change-review', (r, c) => {
  const F = [
    { n:'PricingCard.tsx', h:[ { t:'Use the shared button', l:[['ctx',14,'  return ('],['del',15,'    <button className="cta-old">'],['add',15,'    <Button variant="primary">'],['ctx',16,'      {plan.cta}']] }, { t:'Drop the second CTA', l:[['del',22,'    <a href="/contact">Talk to sales</a>'],['ctx',22,'  </Card>']] } ] },
    { n:'tokens.css', h:[ { t:'Raise muted text contrast', l:[['ctx',8,':root {'],['del',9,'  --text-muted: #c9cfd8;'],['add',9,'  --text-muted: #5b6472;'],['ctx',10,'  --radius-card: 16px;']] } ] },
    { n:'pricing.mdx', h:[ { t:'Move the FAQ below the table', l:[['del',31,'<FAQ />'],['ctx',31,'<CompareTable />'],['add',32,'<FAQ />']] } ] }
  ];
  const files = $('.crx-files', r), diff = $('.crx-diff', r), fn = $('.crx-fn', r);
  let add = 0, del = 0; F.forEach(f => f.h.forEach(h => h.l.forEach(l => { if (l[0] === 'add') add++; if (l[0] === 'del') del++; h.s = h.s || ''; })));
  $('.crx-tot', r).innerHTML = `<span style="color:var(--dm-ok)">+${add}</span> <span style="color:var(--dm-bad)">−${del}</span>`;
  files.innerHTML = F.map((f, i) => `<button class="crx-f" data-i="${i}"><span class="ft ${f.n.endsWith('tsx') ? 're' : ''}">${f.n.split('.').pop().toUpperCase()}</span><span class="nm">${f.n}</span><span class="st"><span class="dot"></span></span></button>`).join('');
  let cur = 0;
  const esc = s => s.replace(/&/g,'&amp;').replace(/</g,'&lt;');
  function fileState(i){ const hs = F[i].h, b = $$('.crx-f', files)[i]; const all = s => hs.every(h => h.s === s); b.classList.toggle('kept', all('kept')); b.classList.toggle('undone', all('undone')); $('.st', b).innerHTML = all('kept') ? I('check','xs') : all('undone') ? I('undo','xs') : hs.some(h => h.s) ? '<span class="dot" style="color:var(--dm-accent-mark,var(--dm-accent))"></span>' : '<span class="dot"></span>'; }
  function show(i, quiet){
    cur = i; $$('.crx-f', files).forEach((b, j) => b.classList.toggle('on', j === i)); swap(fn, 'src/' + F[i].n);
    diff.innerHTML = F[i].h.map((h, k) => `<div class="crx-hk ${h.s}" data-k="${k}"><div class="crx-hh">${I('spark','xs')}<span>${h.t}</span><span class="sp"></span><button class="pill ghost hk-u" aria-pressed="${h.s === 'undone'}">Undo</button><button class="pill hk-k" aria-pressed="${h.s === 'kept'}">Keep</button></div>${h.l.map(l => `<div class="crx-l ${l[0]}"><span class="ln">${l[1]}</span><span class="c">${esc(l[2])}</span><button class="cm" aria-label="Comment on line" data-tip="Comment">${I('plus','xs')}</button></div>`).join('')}</div>`).join('');
    if (!quiet) stagger($$('.crx-hk', diff), 70);
    $$('.crx-hk', diff).forEach(hk => { const h = F[i].h[+hk.dataset.k];
      const setS = s => { h.s = h.s === s ? '' : s; hk.className = 'crx-hk ' + h.s; $('.hk-k', hk).setAttribute('aria-pressed', String(h.s === 'kept')); $('.hk-u', hk).setAttribute('aria-pressed', String(h.s === 'undone')); fileState(i); };
      $('.hk-k', hk).onclick = () => setS('kept'); $('.hk-u', hk).onclick = () => setS('undone');
      $$('.cm', hk).forEach(b => b.onclick = () => { const ln = b.closest('.crx-l'); if (ln.nextElementSibling?.classList.contains('crx-cmt')) return;
        const box = html(`<div class="crx-cmt"><input placeholder="Ask the agent about this line"><button class="pill accent sm">Send</button></div>`); ln.after(box); enter(box); const inp = $('input', box); inp.focus({ preventScroll:true });
        const send = () => { const v = inp.value.trim() || 'Why this change?'; box.className = 'crx-cmt sent'; box.innerHTML = `${I('at','xs')}<span>${esc(v)}</span>`; enter(box); };
        $('button', box).onclick = send; inp.onkeydown = e => { if (e.key === 'Enter') send(); if (e.key === 'Escape') box.remove(); }; });
    });
  }
  $$('.crx-f', files).forEach(b => b.onclick = () => show(+b.dataset.i));
  const bulk = s => { F[cur].h.forEach(h => h.s = s); fileState(cur); show(cur); if (s === 'kept' && cur < F.length - 1) c.later(500, () => show(cur + 1)); };
  $('.crx-ok', r).onclick = () => bulk('kept'); $('.crx-rej', r).onclick = () => bulk('undone');
  F.forEach((_, i) => fileState(i)); show(0, true);
});
